package com.chesspulseai.mapper; import com.chesspulseai.dto.*; import com.chesspulseai.entity.*; import org.springframework.stereotype.Component; import java.util.UUID;
@Component public class GameMapper { public GameResponse game(Game g){return new GameResponse(UUID.fromString(g.getPublicId()),g.getWhitePlayer(),g.getBlackPlayer(),g.getPlayerColor(),g.getStatus(),g.getResult(),g.getStartTime(),g.getEndTime(),g.getCreatedAt(),g.getMoves().size());} public MoveResponse move(ChessMove m){return new MoveResponse(m.getMoveNumber(),m.getSan(),m.getFen(),m.getPlayerColor(),m.getAnalysis()==null?null:analysis(m.getAnalysis()));} public AnalysisResponse analysis(PositionAnalysis a){return new AnalysisResponse(a.getEvaluation(),a.getMateScore(),a.getBestMove(),a.getPrincipalVariation(),a.getDepth(),new ProbabilityResponse(a.getWhiteProbability(),a.getBlackProbability(),a.getDrawProbability()),a.getGamePhase(),a.getCoachingExplanation());}}
